runtime.setup_command:
&{
  cd $HOME
  $null = mkdir -Force llama-cuda
  cd .\llama-cuda

  $headers = @{}
  if ($env:GITHUB_TOKEN) { $headers['Authorization'] = "Bearer $env:GITHUB_TOKEN" }
  try {
    $release = Invoke-RestMethod -Uri "https://api.github.com/repos/ggml-org/llama.cpp/releases/tags/b10746" -Headers $headers
  } catch {
    throw "Failed to query the GitHub Releases API: $($_.Exception.Message)"
  }

  $cudaAsset  = $release.assets | Where-Object { $_.name -like "cudart-llama-bin-win-cuda-*-x64.zip" } | Select-Object -First 1
  $llamaAsset = $release.assets | Where-Object { $_.name -like "llama-*-bin-win-cuda-*-x64.zip" }       | Select-Object -First 1
  if (-not $cudaAsset -or -not $llamaAsset) {
    throw "No matching Windows CUDA release asset found for $($release.tag_name)."
  }

  Invoke-WebRequest -Uri $cudaAsset.browser_download_url  -OutFile $cudaAsset.name
  Invoke-WebRequest -Uri $llamaAsset.browser_download_url -OutFile $llamaAsset.name

  Expand-Archive $cudaAsset.name  .\llama -Force
  Expand-Archive $llamaAsset.name .\llama -Force

  cd .\llama
  $env:PATH = "$PWD;$env:PATH"
}

